CREATE TYPE "IngestionRunStatus" AS ENUM ('RUNNING','COMPLETED','PARTIAL','FAILED');
CREATE TYPE "IngestionTrigger" AS ENUM ('SCHEDULE','MANUAL','API','TEST');
CREATE TYPE "IngestionAttemptStatus" AS ENUM ('UNCHANGED','REVIEW','PUBLISHABLE','FAILED');
CREATE TYPE "IngestionReviewState" AS ENUM ('PENDING','APPROVED','REJECTED','SUPERSEDED','PUBLISHED');
CREATE TABLE "IngestionRun" ("id" TEXT PRIMARY KEY, "schemaVersion" INTEGER NOT NULL, "trigger" "IngestionTrigger" NOT NULL, "sourceCommit" TEXT NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "endedAt" TIMESTAMP(3), "status" "IngestionRunStatus" NOT NULL DEFAULT 'RUNNING', "totalSources" INTEGER NOT NULL DEFAULT 0, "successful" INTEGER NOT NULL DEFAULT 0, "unchanged" INTEGER NOT NULL DEFAULT 0, "reviewRequired" INTEGER NOT NULL DEFAULT 0, "publishable" INTEGER NOT NULL DEFAULT 0, "failed" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "IngestionSourceState" ("festivalSlug" TEXT PRIMARY KEY, "lastSuccessfulCheck" TIMESTAMP(3), "lastAttemptId" TEXT, "updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "IngestionAttempt" ("id" TEXT PRIMARY KEY, "runId" TEXT NOT NULL, "festivalSlug" TEXT NOT NULL, "requestedUrl" TEXT NOT NULL, "finalUrl" TEXT, "httpStatus" INTEGER, "durationMs" INTEGER NOT NULL, "retryCount" INTEGER NOT NULL DEFAULT 0, "error" TEXT, "parserVersions" JSONB NOT NULL, "status" "IngestionAttemptStatus" NOT NULL, "startedAt" TIMESTAMP(3) NOT NULL, "endedAt" TIMESTAMP(3) NOT NULL, "priorAttemptId" TEXT);
CREATE TABLE "IngestionCandidate" ("id" TEXT PRIMARY KEY, "runId" TEXT NOT NULL, "attemptId" TEXT NOT NULL UNIQUE, "festivalSlug" TEXT NOT NULL, "schemaVersion" INTEGER NOT NULL, "sourceEdition" TEXT, "sourceYear" INTEGER, "normalized" JSONB NOT NULL, "warnings" JSONB NOT NULL, "publishable" BOOLEAN NOT NULL, "reviewState" "IngestionReviewState" NOT NULL DEFAULT 'PENDING', "reviewActor" TEXT, "reviewedAt" TIMESTAMP(3), "publishedAt" TIMESTAMP(3), "supersedesId" TEXT, "catalogueVersion" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "IngestionEvidence" ("id" TEXT PRIMARY KEY, "candidateId" TEXT NOT NULL, "field" TEXT NOT NULL, "observedValue" JSONB, "sourceUrl" TEXT NOT NULL, "excerpt" TEXT, "contentHash" TEXT NOT NULL, "observedAt" TIMESTAMP(3) NOT NULL, "adapter" TEXT NOT NULL);
CREATE TABLE "IngestionDiff" ("id" TEXT PRIMARY KEY, "candidateId" TEXT NOT NULL, "field" TEXT NOT NULL, "beforeValue" JSONB, "afterValue" JSONB, "reviewRequired" BOOLEAN NOT NULL, "policyVersion" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX "IngestionAttempt_runId_festivalSlug_key" ON "IngestionAttempt"("runId","festivalSlug");
CREATE INDEX "IngestionRun_startedAt_idx" ON "IngestionRun"("startedAt"); CREATE INDEX "IngestionAttempt_festivalSlug_endedAt_idx" ON "IngestionAttempt"("festivalSlug","endedAt"); CREATE INDEX "IngestionCandidate_festivalSlug_createdAt_idx" ON "IngestionCandidate"("festivalSlug","createdAt"); CREATE INDEX "IngestionEvidence_candidateId_field_idx" ON "IngestionEvidence"("candidateId","field"); CREATE INDEX "IngestionDiff_candidateId_createdAt_idx" ON "IngestionDiff"("candidateId","createdAt");
ALTER TABLE "IngestionAttempt" ADD CONSTRAINT "IngestionAttempt_runId_fkey" FOREIGN KEY ("runId") REFERENCES "IngestionRun"("id") ON DELETE CASCADE;
ALTER TABLE "IngestionCandidate" ADD CONSTRAINT "IngestionCandidate_runId_fkey" FOREIGN KEY ("runId") REFERENCES "IngestionRun"("id") ON DELETE RESTRICT; ALTER TABLE "IngestionCandidate" ADD CONSTRAINT "IngestionCandidate_attemptId_fkey" FOREIGN KEY ("attemptId") REFERENCES "IngestionAttempt"("id") ON DELETE RESTRICT;
ALTER TABLE "IngestionEvidence" ADD CONSTRAINT "IngestionEvidence_candidateId_fkey" FOREIGN KEY ("candidateId") REFERENCES "IngestionCandidate"("id") ON DELETE CASCADE; ALTER TABLE "IngestionDiff" ADD CONSTRAINT "IngestionDiff_candidateId_fkey" FOREIGN KEY ("candidateId") REFERENCES "IngestionCandidate"("id") ON DELETE CASCADE;
